using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad]public static class RadarRocketVerification {
  const string Key="RadarRocketVerification";static double start;static readonly List<string> rows=new List<string>();
  static RadarRocketVerification(){if(SessionState.GetBool(Key,false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
  public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");SessionState.SetBool(Key,true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
  static void Check(bool ok,string m){if(!ok)throw new Exception(m);rows.Add("PASS "+m);Debug.Log("RADAR_ROCKET_PASS "+m);}
  static void Near(float a,float b,string m){Check(Mathf.Abs(a-b)<.001f,m+" "+a+" = "+b);}
  static bool Button(CampaignHUD h,string text){return h.GetComponentsInChildren<Button>(true).Any(b=>b.gameObject.activeInHierarchy&&b.GetComponentInChildren<Text>()!=null&&b.GetComponentInChildren<Text>().text==text);}
  static void Test(BattleWorld w){
   var opening=w.GetComponent<LocalOpeningGarrison>();Check(opening!=null&&opening.initialArmyCount==opening.initialInsideCount&&opening.initialArmyCount==w.units.Count(u=>u!=null&&u.Alive&&u.GetComponent<RadarInstallation>()==null),"all starting armies including rockets began inside own cities");Check(w.units.All(u=>!u.Alive||u.GetComponent<RadarInstallation>()!=null||u.Point!=null&&!u.OnMap),"opening armies actually inside cities before player orders");Check(w.units.Count(u=>u.combatDefinition.role==UnitRole.RocketArtillery)==2,"both factions start with rocket artillery");w.enabled=false;foreach(var initial in w.units)if(initial!=null&&initial.Point!=null)initial.BeginExit();w.GetComponent<BattleAIController>().enabled=false;w.GetComponent<AIBasicCommander>().enabled=false;w.SetPlayer("A");w.fogEnabled=true;foreach(var u in w.units){u.Motor.Stop();u.transform.position=new Vector3(u.ownerId=="A"?-44:44,-27);}
   Check(typeof(CombinedArmsWorld).GetMethod("Support")==null&&typeof(CombinedArmsWorld).GetField("supportDefinition")==null,"fire-support logic and settings removed");Check(!Enum.GetNames(typeof(BattleCommandKind)).Contains("ArtillerySupport")&&!Enum.GetNames(typeof(CampaignHUD.Tool)).Contains("Support"),"fire-support command and aim tool removed");Check(!File.Exists("Assets/Game/Data/CombinedArms/DefaultSupport.asset")&&!File.Exists("Assets/Game/Data/Effects/SupportEffects.asset"),"dedicated support assets removed");
   var engineer=w.units.First(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Engineer);var infantry=w.units.First(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry);Near(engineer.GetComponent<ArmyRoadMover>().Speed,infantry.GetComponent<ArmyRoadMover>().Speed,"engineer road speed equals infantry");foreach(var k in new[]{TerrainKind.Ground,TerrainKind.Grass,TerrainKind.Forest,TerrainKind.Mountain})Near(engineer.GetComponent<ArmyFreeMarchMover>().SpeedAt(k),infantry.GetComponent<ArmyFreeMarchMover>().SpeedAt(k),"engineer terrain speed equals infantry "+k);
   Vector3 forest=default;bool found=false;for(float y=-27;y<27&&!found;y+=1)for(float x=-44;x<44;x+=1){var p=new Vector3(x,y);if(w.setup.freeMarchMap.TerrainAt(new RoadPoint(x,y))!=TerrainKind.Forest)continue;engineer.transform.position=p+Vector3.right*.2f;if(RadarInstallation.CanDeploy(w,engineer,p)){forest=p;found=true;break;}}Check(found,"forest deployment location found");
   var commands=w.GetComponent<BattleCommandService>();Check(commands.Submit(new BattleCommand{kind=BattleCommandKind.DeployRadar,unitId=engineer.unitId,playerId="A",destination=forest}).accepted,"engineer deploys radar in forest");var radar=w.units.Last(u=>u.combatDefinition.role==UnitRole.Radar);Near(radar.combatDefinition.visionRadius,10,"radar vision stays 10 km");Check(!radar.CanMove&&!radar.CanFire&&!radar.combatDefinition.canHideInForest&&!radar.HideInForest(),"radar immobile unarmed and cannot hide");Check(radar.Motor.MovementLocked,"radar route motor locked");
   Check(!commands.Submit(new BattleCommand{kind=BattleCommandKind.FreeDestination,unitId=radar.unitId,playerId="A",destination=forest+Vector3.right}).accepted,"movement command rejected");Check(!commands.Submit(new BattleCommand{kind=BattleCommandKind.SplitFlank,unitId=radar.unitId,playerId="A"}).accepted,"radar cannot split");Check(!RadarInstallation.Deploy(w,engineer,forest).accepted,"overlapping radar rejected");Check(!RadarInstallation.Deploy(w,infantry,forest+Vector3.right*.8f).accepted,"only engineers deploy radar");Check(!RadarInstallation.Deploy(w,engineer,forest+Vector3.right*5).accepted,"remote radar placement rejected");
   var saved=w.units;w.units=new[]{radar};Check(w.VisibleAt("A",forest+Vector3.right*9.9f)&&!w.VisibleAt("A",forest+Vector3.right*10.1f),"actual detection respects 10 km boundary");var observer=saved.First(u=>u.ownerId=="B");observer.transform.position=forest+Vector3.right*.4f;w.units=new[]{radar,observer};Check(w.IsVisible("B",radar),"enemy sees radar in forest within own vision");observer.transform.position=forest+Vector3.right*30;Check(!w.IsVisible("B",radar),"radar not globally revealed through fog");w.units=saved;
   var carrier=saved.First(u=>u.ownerId=="A"&&u.GetComponent<PersonnelCarrier>()!=null).GetComponent<PersonnelCarrier>();carrier.transform.position=forest;Check(!carrier.Load(radar).accepted,"fixed radar cannot board vehicle");var city=w.points.First(p=>p.ownerId=="A");Check(!radar.BeginEnter(city),"fixed radar cannot enter city");var hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();hud.SelectUnit(engineer);Check(Button(hud,"部署雷达"),"engineer deployment button connected");hud.SelectUnit(radar);Check(!Button(hud,"藏匿")&&!Button(hud,"停止移动"),"radar panel omits inapplicable controls");
   var shade=w.GetComponent<StaffVisibilityShade>();shade.Gather();Check(shade.ShadeAt(forest+Vector3.right*8).a<.01f,"radar reveals fog shade");
   foreach(var name in new[]{"Radar","Rocket"}){var symbols=Resources.Load<SmoothUnitSymbols>("Radar/"+name+"Symbols");Check(symbols!=null&&symbols.blue.Length==6&&symbols.red.Length==6&&symbols.neutral.Length==6,name+" has six sizes and three factions");foreach(int size in symbols.displayWidths){var sprite=symbols.Select(size,"A");Check(sprite.texture.width>=512&&sprite.texture.filterMode==FilterMode.Bilinear,name+" smooth high-resolution source at "+size+" px");}}
   var production=w.GetComponent<InfantryProduction>();city.resourceStock=20000;Check(LevelUnitAvailability.Allowed(w,UnitRole.RocketArtillery)&&!LevelUnitAvailability.Allowed(w,UnitRole.Radar),"rocket available in city; radar engineer-only");Check(production.Queue("A",city,ArmyEchelon.Company,false,1,UnitRole.RocketArtillery),"rocket production queues");production.Tick(production.Duration(ArmyEchelon.Company,UnitRole.RocketArtillery)+.1f);var rocket=w.units.Last(u=>u.combatDefinition.role==UnitRole.RocketArtillery&&u.ownerId=="A");Check(rocket.GetComponent<SmoothUnitSymbolView>()!=null,"produced rocket uses new symbol");var battery=rocket.GetComponent<ArtilleryBattery>();Near(battery.definition.range,16,"company rocket range twice artillery");Check(!rocket.CanFire&&battery.Ready,"rocket uses manual artillery logic");
   foreach(var u in w.units)if(u.ownerId=="A"&&u!=rocket)u.transform.position=new Vector3(-44,-27);rocket.transform.position=Vector3.zero;var target=Vector3.right*12;Check(!w.VisibleAt("A",target),"rocket test target outside friendly vision");hud.SelectUnit(rocket);hud.ToggleTool(CampaignHUD.Tool.Artillery);hud.Preview(target);Check(hud.PreviewValid,"aim preview permits blind fire");Check(battery.Fire(w,"A",target).accepted,"rocket fires at unseen in-range location");Check(!battery.Fire(w,"A",target).accepted,"rocket keeps ordinary cooldown");w.GetComponent<CombinedArmsWorld>().Tick(battery.definition.cooldownSeconds+.1f);Check(!battery.Fire(w,"A",Vector3.right*16.1f).accepted,"rocket still rejects beyond range");Check(!battery.Fire(w,"B",target).accepted,"rocket ownership enforced");
   var artillery=w.units.First(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Artillery);artillery.transform.position=Vector3.zero;var ordinary=artillery.GetComponent<ArtilleryBattery>();ordinary.Tick(999);Check(!w.VisibleAt("A",Vector3.right*7)&&ordinary.Fire(w,"A",Vector3.right*7).accepted,"ordinary artillery also fires without vision");
   rocket.combatDefinition.echelon=ArmyEchelon.Battalion;PlannedUnitRanges.ApplyTo(rocket);Near(battery.definition.range,20,"rocket echelon range scaling retained");radar.Damage(10000);w.units=new[]{radar};Check(!w.VisibleAt("A",radar.transform.position),"destroyed radar stops reconnaissance");w.units=saved.Concat(new[]{rocket}).ToArray();
   var ownCity=w.points.First(p=>p.ownerId=="A");var enemyCity=w.points.First(p=>p.ownerId=="B");infantry.UnderFire=false;infantry.BeginEnter(ownCity);observer.UnderFire=false;observer.BeginEnter(enemyCity);var aiController=w.GetComponent<BattleAIController>();aiController.enabled=true;aiController.aiEnabled=true;opening.Tick(4);Check(observer.OnMap&&infantry.Point==ownCity&&!infantry.OnMap,"PVE AI can leave its opening city while player garrison stays");aiController.enabled=false;infantry.BeginExit();
   Check(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(Resources.Load<GameObject>("Radar/Radar"))==0&&GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(Resources.Load<GameObject>("Radar/RocketArtillery"))==0,"both new prefabs have no missing scripts");
  }
  static void Poll(){try{if(EditorApplication.timeSinceStartup-start>120)throw new Exception("timeout");if(!EditorApplication.isPlaying||Time.time<.7f)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;Test(w);Finish(null);}catch(Exception e){Finish(e);}}
  static void Finish(Exception e){if(e!=null){rows.Add("FAIL "+e);Debug.LogException(e);}File.WriteAllText("C:/Users/ZWQ/Documents/Codex/2026-10-19/c-desktop-wargame-9/work/radar-rocket-20261020/verification.txt",string.Join("\n",rows));SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(e==null?0:1);}
 }
}
